#!/usr/bin/env bash
# СУДИТ: hooks/fsrs-lib.sh docs/architecture.md
# probe_D1351.sh — объявление единицы «день опыта» говорит то, что считает счётчик: 30 УНИКАЛЬНЫХ сессий с округлением
# к ближайшему, а не «медиана сессий за день».
#
# Повод (21 ноября 2026). Постоянную 30 сняли 31 августа с ЗАПИСЕЙ реестра за день, а счётчик делит на неё число
# уникальных сессий (у сессии в среднем 8 записей): «день опыта» равен 4–7 рабочим дням, и объявление «медиана сессий
# за активный день» было ложным с первого дня. Решение владельца: ритм оставить, объявление исправить.
# Две ноги. Текст: ни библиотека, ни архитектурный документ не выводят постоянную из «медианы сессий за … день».
# Поведение (оно же контроль, что новое объявление правдиво) — на ОБОИХ входах счётчика, по мгновению и по дате
# (вторым стареют знания; первая редакция пробы судила один, скептик opus, M1): пороги 14 → 0, 15 → 1, 44 → 1,
# 45 → 2 держат и число 30, и округление к ближайшему (M2: пара «30 → 1, 4 → 0» проходила при темпе от 21 до 60);
# у каждой сессии по три записи, а 92 записи четырёх сессий дают 0 — счёт идёт по сессиям, не по записям.
# Проверка результата: bash hooks/tests/fixtures/probe_D1351.sh → 0 — объявление верно; 1 — ложное объявление на
#   месте либо счётчик считает иначе; 2 — не измерено (нет библиотеки, jq либо счётчик не ответил числом).
set -uo pipefail
REPO="${CLAUDSOUL_REPO:-$(cd "$(dirname "$0")/../../.." && pwd)}"
LIB="$REPO/hooks/fsrs-lib.sh"; DOC="$REPO/docs/architecture.md"
[ -f "$LIB" ] && command -v jq >/dev/null 2>&1 || { echo "нет библиотеки либо jq — не измерено"; exit 2; }
W=$(mktemp -d) || exit 2
trap 'rm -rf "$W"' EXIT
EPOCH=1760000000; DAY="2025-10-09"   # одно и то же «до»: записи песочницы — 20–22 октября 2025
mkreg() {   # <файл> <уникальных сессий> <записей на сессию>
    local f="$1" s r; : > "$f"
    for s in $(seq 1 "$2"); do for r in $(seq 1 "$3"); do
        printf '{"session_id":"s%s","started_at":"2025-10-2%sT1%s:00:00Z"}\n' "$s" "$((r % 3))" "$((r % 10))" >> "$f"
    done; done
}
days() {   # <реестр> <вход: epoch|date> → дней опыта после отметки
    ( FSRS_SESSION_REGISTRY="$1"; unset FSRS_SESSIONS_PER_DAY
      [ -f "$REPO/hooks/portable-lib.sh" ] && . "$REPO/hooks/portable-lib.sh" 2>/dev/null
      . "$LIB" 2>/dev/null || exit 2
      if [ "$2" = epoch ]; then fsrs_experience_days_since_epoch "$EPOCH" 2>/dev/null
      else fsrs_experience_days_since "$DAY" 2>/dev/null; fi )
}
bad=""
while read -r n rec want; do
    mkreg "$W/r$n-$rec.jsonl" "$n" "$rec"
    for how in epoch date; do
        got=$(days "$W/r$n-$rec.jsonl" "$how")
        case "$got" in ''|*[!0-9]*) echo "счётчик (вход ${how}) не ответил числом на ${n} сессиях: «${got}» — не измерено"; exit 2 ;; esac
        [ "$got" = "$want" ] || bad="${bad:+$bad; }вход ${how}: ${n} сессий по ${rec} записи дали ${got} дн., ждали ${want}"
    done
done <<'CASES'
14 3 0
15 3 1
44 3 1
45 3 2
4 23 0
CASES
for f in "$LIB" "$DOC"; do
    [ -f "$f" ] || continue
    if grep -q 'медиана сессий за' "$f"; then bad="${bad:+$bad; }${f##*/} выводит постоянную из «медианы сессий за день»"; fi
done
if [ -n "$bad" ]; then echo "$bad"; exit 1; fi
echo "объявление дня опыта верно: 30 уникальных сессий, округление к ближайшему"
exit 0
